483	                >
484	                  <Text variant="labelMedium" color={palette.onSurfaceVariant} style={{ marginRight: spacing.sm, minWidth: 56 }}>
485	                    {t('pack')} {i + 1}
486	                  </Text>
487	                  <Calendar size={18} color={palette.onSurfaceVariant} strokeWidth={2} />
488	                  <Text
489	                    variant="bodyLarge"
490	                    color={d ? palette.onSurface : palette.onSurfaceVariant}
491	                    style={{ marginLeft: spacing.sm, flex: 1, letterSpacing: 1 }}
492	                  >
