497	              {showPicker && editingPackIdx != null && (
498	                <DatePickerModal
499	                  visible={showPicker}
500	                  value={perPackExpiries[editingPackIdx]}
501	                  minimumDate={new Date()}
502	                  onSelect={(date) => {
503	                    setPerPackExpiries((prev) => prev.map((p, i) => (i === editingPackIdx ? date : p)));
504	                  }}
505	                  onDismiss={() => { setShowPicker(false); setEditingPackIdx(null); }}
506	                />
507	              )}
