513	            style={styles.noExpiryRow}
514	          >
515	            <View
516	              style={[
517	                styles.checkbox,
518	                {
519	                  backgroundColor: noExpiry ? palette.primary : 'transparent',
520	                  borderColor: noExpiry ? palette.primary : palette.outline,
521	                },
522	              ]}
523	            >
524	              {noExpiry && <Check size={14} color={palette.onPrimary} strokeWidth={3} />}
525	            </View>
526	            <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
527	              {t('noExpiry')}
528	            </Text>
529	          </Pressable>
530	        </View>
531	      </ScrollView>
532	
533	        <View style={[styles.footer, { backgroundColor: palette.surface, borderTopColor: palette.outlineVariant }]}>
534	          {/* Primary action: add to order session */}
535	          <Button
536	            label={t('addToOrder')}
537	            onPress={addToSession}
538	            loading={saving}
539	            size="lg"
540	            fullWidth
541	            leadingIcon={<Check size={22} color={palette.onPrimary} strokeWidth={2.4} />}
542	          />
543	          {/* Secondary: standalone receipt (when not in a multi-scan flow) */}
544	          {!orderSession.isActive && mismatch && (
545	            <Button
546	              label={t('flagAndContinue')}
547	              onPress={flagAndContinueStandalone}
548	              variant="danger"
549	              loading={saving}
550	              size="md"
551	              fullWidth
552	              style={{ marginTop: spacing.sm }}
553	            />
554	          )}
555	          <Button
556	            label={t('cancel')}
557	            variant="text"
558	            onPress={() => navigation.popToTop()}
559	            style={{ marginTop: spacing.sm }}
560	          />
561	        </View>
562	      </View>
563	    </KeyboardAvoidingView>
564	  );
565	}
